import './comparison.js?v=18';
import {excelBytes,importPlan,saveFile,payload} from './files.js?v=18';
import {calculate,clean,DEFAULTS} from './engine.js?v=11';
const $=id=>document.getElementById(id),money=new Intl.NumberFormat('cs-CZ',{maximumFractionDigits:0}),fmt=n=>money.format(n)+' Kč',num=n=>money.format(n),pct=n=>new Intl.NumberFormat('cs-CZ',{maximumFractionDigits:8}).format(n*100)+' %';
let state={...DEFAULTS},result,timer;const storageKey='muj-dip-plan-v1';
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function sync(){for(const el of document.querySelectorAll('[data-key]'))el.value=state[el.dataset.key];}
function setText(id,text){$(id).textContent=text;}
function render(){result=calculate(state);const r=result,s=r.s;state=s;setText('portfolio',fmt(r.end.value));setText('endAge','V '+(s.age+s.years)+' letech');setText('yearsText',s.years);setText('horizonLabel',s.years+' let');setText('realValue',fmt(r.end.real));setText('totalDeposits',fmt(r.end.own+r.end.employer));setText('gain',fmt(r.end.gain));setText('taxSaving',fmt(r.personalTax));setText('employerAnnual',fmt(s.employer*12));setText('withdrawAge','Od '+r.eligibleAge+' let');setText('chartPeriod',s.years+' LET');setText('chartNote','Modelový výnos '+pct(r.netRate)+' ročně; inflace '+pct(s.inflation/100)+' ročně. Modrá: hodnota investice s výnosem. Červená: její kupní síla v dnešních cenách. Daňová úspora je mimo graf.');
const eligible=$('eligibility');eligible.classList.toggle('warning',!r.eligible);eligible.textContent=r.eligible?'✓ Zvolený horizont splňuje základní podmínky 120 měsíců a věku 60 let. Model nepočítá s předčasným výběrem.':'ⓘ Zvolený horizont zatím nesplňuje obě podmínky DIP. Při založení nyní vychází nejbližší výběr se zachováním podpory přibližně od '+r.eligibleAge+' let.';
for(const button of document.querySelectorAll('[data-own]'))button.classList.toggle('selected',Number(button.dataset.own)===s.own);
const rows=r.points;$('yearRows').innerHTML=rows.map(p=>`<tr><td>${p.year===0?'Počátek':p.year+'. rok'} <span class="muted">/ ${s.age+p.year} let</span></td><td>${fmt(p.own)}</td><td>${fmt(p.employer)}</td><td class="nominal-value">${fmt(p.value)}</td><td class="real-value">${fmt(p.real)}</td><td>${fmt(p.tax)}</td></tr>`).join('');
const budget=s.mode==='budget';setText('companyHeadline',budget?'ROČNÍ INVESTICE DO VAŠEHO TÝMU':'ROČNÍ ÚSPORA VAŠÍ FIRMY');setText('companyTotal',fmt((budget?r.dipCost:r.companySaving)*s.employees));setText('companyExplain',budget?'Stejný rozpočet firmy v obou variantách.':'oproti navýšení hrubé mzdy o '+fmt(s.employer)+' měsíčně na osobu');setText('companyBudget',fmt(r.dipCost*s.employees));setText('companyWageTotal',fmt(r.wageCost*s.employees));setText('employeeExtra',fmt(r.employeeDifference));
const compare=[['Hrubá částka / příspěvek',r.raise,s.employer*12],['Odvody firmy navíc',r.wageCost-r.raise,r.dipCost-s.employer*12],['Celkový náklad firmy',r.wageCost,r.dipCost],['Odvody a daň zaměstnance',r.raise-r.wageNet,r.dipTaxCost],['Hodnota po dani a odvodech',r.wageNet,r.dipNetBenefit]];
$('compareRows').innerHTML=compare.map(([label,a,b])=>`<tr><td>${label}</td><td>${fmt(a)}</td><td>${fmt(b)}</td></tr>`).join('');
const max=Math.max(1,r.wageNet,r.dipNetBenefit);$('benefitBars').innerHTML=[['Mzda na účet',r.wageNet],['DIP po odvodech',r.dipNetBenefit]].map(([label,value])=>`<div class="bar-row"><span>${label}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(0,value/max*100)}%"></div></div><strong>${fmt(value)}</strong></div>`).join('');
const ew=$('employerWarning');ew.classList.toggle('warning',r.taxable>0);ew.textContent=r.taxable>0?'ⓘ Příspěvek překračuje dostupný limit osvobození o '+fmt(r.taxable)+' ročně na osobu. Model zahrnuje dodatečnou daň a odvody. Jejich dopad na zaměstnance je '+fmt(r.dipTaxCost)+' ročně.':'✓ Celý příspěvek '+fmt(s.employer*12)+' ročně na osobu se vejde do zbývajícího limitu osvobození. Započteny jsou i jiné zadané příspěvky zaměstnavatele.';
setText('companySummary','Při '+num(s.employees)+' zaměstnancích a příspěvku '+fmt(s.employer)+' měsíčně činí roční náklad firmy '+fmt(r.dipCost*s.employees)+'. '+(budget?'Při stejném rozpočtu by roční zvýšení čisté mzdy jednoho zaměstnance bylo '+fmt(r.wageNet)+'.':'Roční rozdíl nákladů proti navýšení hrubé mzdy o stejnou částku je '+fmt(r.companySaving*s.employees)+'.')+' Roční hodnota příspěvku na DIP po zohlednění případné daně a odvodů je '+fmt(r.dipNetBenefit)+' na osobu.');drawChart(r);
}
function drawChart(r){const W=Math.max(280,Math.min(900,$("chart").clientWidth||780)),H=W<480?260:270,L=62,R=16,T=18,B=32,plotW=W-L-R,plotH=H-T-B;const max=Math.max(1,...r.points.map(p=>Math.max(p.value,p.own+p.employer))),step=Math.pow(10,Math.floor(Math.log10(max))),top=Math.ceil(max/step)*step;const x=i=>L+i/r.s.years*plotW,y=v=>T+plotH-v/top*plotH;const line=key=>r.points.map(p=>`${x(p.year).toFixed(2)},${y(key(p)).toFixed(2)}`).join(' ');const area=(low,high)=>`${line(high)} ${[...r.points].reverse().map(p=>`${x(p.year).toFixed(2)},${y(low(p)).toFixed(2)}`).join(' ')}`;let svg=`<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg"><title>Hodnota DIP po ${r.s.years} letech: ${fmt(r.end.value)}</title>`;
for(let i=0;i<=4;i++){const v=top*i/4;svg+=`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#ede4d3"/><text x="${L-10}" y="${y(v)+3}" text-anchor="end" font-size="11" fill="#827253">${v>=1e6?num(v/1000)+' tis.':num(v)}</text>`;}
svg+=`<polygon points="${area(()=>0,p=>p.own)}" fill="#ece0c5"/><polygon points="${area(p=>p.own,p=>p.own+p.employer)}" fill="#cbb17b"/>`;
if(r.end.gain>=0)svg+=`<polygon points="${area(p=>p.own+p.employer,p=>p.value)}" fill="#a67d35" fill-opacity=".22"/>`;
svg+=`<polyline points="${line(p=>p.value)}" fill="none" stroke="#2563eb" stroke-width="3" stroke-linejoin="round"/><circle cx="${x(r.s.years)}" cy="${y(r.end.value)}" r="4" fill="#2563eb" stroke="white" stroke-width="2"/>`;
svg+=`<polyline points="${line(p=>p.real)}" fill="none" stroke="#dc2626" stroke-width="2.5" stroke-dasharray="7 4" stroke-linejoin="round"><title>Po inflaci: ${fmt(r.end.real)}</title></polyline><circle cx="${x(r.s.years)}" cy="${y(r.end.real)}" r="4" fill="#dc2626" stroke="white" stroke-width="2"/>`;
const ticks=[...new Set(W<480?[0,Math.round(r.s.years/2),r.s.years]:[0,Math.round(r.s.years/4),Math.round(r.s.years/2),Math.round(r.s.years*3/4),r.s.years])];for(const tick of ticks)svg+=`<text x="${x(tick)}" y="${H-7}" text-anchor="${tick===0?'start':tick===r.s.years?'end':'middle'}" font-size="11" fill="#827253">${tick} ${tick===1?'rok':'let'}</text>`;svg+='</svg>';$('chart').innerHTML=svg;$('chart').setAttribute('aria-label',`Hodnota DIP za ${r.s.years} let: ${fmt(r.end.value)}; po inflaci ${fmt(r.end.real)}; vklady ${fmt(r.end.own+r.end.employer)}.`);}
function tab(name){for(const el of document.querySelectorAll('.panel'))el.hidden=el.id!==name;for(const el of document.querySelectorAll('[data-tab]')){const active=el.dataset.tab===name;el.classList.toggle('active',active);if(el.getAttribute('role')==='tab')el.setAttribute('aria-selected',String(active));}}
for(const el of document.querySelectorAll('[data-tab]'))el.addEventListener('click',()=>tab(el.dataset.tab));
for(const el of document.querySelectorAll('[data-key]')){const handler=()=>{if(el.type==='number'&&!el.checkValidity())return;const value=el.dataset.key==='mode'?el.value:Number(el.value);state=clean({...state,[el.dataset.key]:value});for(const peer of document.querySelectorAll(`[data-key="${el.dataset.key}"]`))if(peer!==el)peer.value=state[el.dataset.key];render();};el.addEventListener('input',handler);el.addEventListener('change',()=>{state=clean({...state,[el.dataset.key]:el.dataset.key==='mode'?el.value:Number(el.value)});sync();render();});}
for(const b of document.querySelectorAll('[data-own]'))b.addEventListener('click',()=>{state.own=Number(b.dataset.own);sync();render();});
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('save').addEventListener('click',()=>{try{localStorage.setItem(storageKey,JSON.stringify(state));toast('Plán je uložen v tomto prohlížeči.');}catch{toast('Uložení není dostupné. Použijte Export.');}});
$('export').addEventListener('click',async()=>{const format=$('exportFormat').value;try{toast('Připravuji export…');if(format==='xlsx')saveFile('MUJ-DIP-plan.xlsx',excelBytes(result),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');else if(format==='json')saveFile('MUJ-DIP-plan.json',JSON.stringify(payload(state),null,2),'application/json');else{const {exportPdf}=await import('./pdf.js?v=18');await exportPdf(result,format);}toast('Export je připraven ke stažení.');}catch(error){toast(error.message||'Export se nepodařilo vytvořit.');}});
$('import').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{state=await importPlan(file);sync();render();toast('Plán byl načten ze souboru.');}catch(error){toast(error.message||'Soubor nelze načíst.');}finally{e.target.value='';}});
$('reset').addEventListener('click',()=>{state={...DEFAULTS};sync();render();toast('Obnoven výchozí příklad. Uložený plán zůstává zachován.');});
$('clear').addEventListener('click',()=>{try{localStorage.removeItem(storageKey);toast('Uložený plán byl vymazán z prohlížeče.');}catch{toast('Úložiště prohlížeče není dostupné.');}});
$('csv').addEventListener('click',()=>{const rows=[['Rok','Vek','Vlastni vklady Kc','Prispevky firmy Kc','Hodnota DIP Kc','Zhodnoceni Kc','Danova uspora mimo DIP Kc','Hodnota v dnesnich cenach Kc'],...result.points.map(p=>[p.year,state.age+p.year,p.own,p.employer,p.value,p.gain,p.tax,p.real].map(n=>Math.round(n)))];download('muj-dip-vyvoj.csv','\uFEFF'+rows.map(r=>r.join(';')).join('\r\n'),'text/csv;charset=utf-8');});
$('print').addEventListener('click',async()=>{try{toast('Připravuji PDF přehled…');const {exportPdf}=await import('./pdf.js?v=18');await exportPdf(result);toast('PDF přehled je připraven ke stažení.');}catch{toast('Přímý export selhal. Otevírám tisk — vyberte Uložit jako PDF.');window.print();}});
try{const saved=localStorage.getItem(storageKey);if(saved)state=clean(JSON.parse(saved));}catch{}sync();render();

const menuToggle=$('menuToggle'),topNav=$('topNav');
function closeMenu(){menuToggle.setAttribute('aria-expanded','false');menuToggle.setAttribute('aria-label','Otevřít menu');topNav.classList.remove('menu-open');}
menuToggle.addEventListener('click',()=>{const open=menuToggle.getAttribute('aria-expanded')!=='true';menuToggle.setAttribute('aria-expanded',String(open));menuToggle.setAttribute('aria-label',open?'Zavřít menu':'Otevřít menu');topNav.classList.toggle('menu-open',open);});
topNav.addEventListener('click',e=>{if(e.target.closest('[data-tab],a[href]'))closeMenu();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menuToggle.getAttribute('aria-expanded')==='true'){closeMenu();menuToggle.focus();}});
document.addEventListener('click',e=>{if(!topNav.contains(e.target)&&!menuToggle.contains(e.target))closeMenu();});

const advancedToggle=$('advancedToggle'),advancedSettings=$('advancedSettings');
advancedToggle.addEventListener('click',()=>{const open=advancedToggle.getAttribute('aria-expanded')!=='true';advancedToggle.setAttribute('aria-expanded',String(open));advancedSettings.hidden=!open;advancedToggle.querySelector('span').textContent=open?'−':'＋';});

document.querySelector('label.import').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('import').click();}});
const compactMenu=window.matchMedia('(max-width:1279px)');compactMenu.addEventListener('change',closeMenu);
let lastChartWidth=0;new ResizeObserver(entries=>{const width=Math.round(entries[0].contentRect.width);if(width>0&&width!==lastChartWidth){lastChartWidth=width;if(result)drawChart(result);}}).observe($('chart'));
